package app.noir.mobile;
import android.app.*;
import android.graphics.Rect;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
final class HomeLayout {
 static final List<String> DEFAULTS=Arrays.asList("continue","list","top10","because","genres","collections","recently-added","services","recently-watched","shows","movies","queue","upcoming");
 static {String[][] words={{"Edit Home","تعديل الرئيسية"},{"Make Home yours","رتّب الرئيسية كما تحب"},{"Continue Watching stays first. Pin genres and collections below.","متابعة المشاهدة أولاً دائمًا. ثبّت الأنواع والمجموعات أدناه."},{"Save Home","حفظ الرئيسية"},{"Because you watched…","لأنك شاهدت…"},{"Because you watched %s","لأنك شاهدت %s"},{"Genres","الأنواع"},{"Poster","ملصقات"},{"Landscape","أفقي"},{"List","قائمة"},{"View","العرض"},{"Card size","حجم البطاقة"},{"Small","صغير"},{"Medium","متوسط"},{"Large","كبير"},{"Pin row","تثبيت الصف"},{"Show row","إظهار الصف"},{"Move earlier","نقل للأعلى"},{"Move later","نقل للأسفل"},{"Still planned","ما زال ضمن الخطط"},{"All","الكل"},{"Shows","مسلسلات"},{"Movies","أفلام"},{"Your play queue","قائمة التشغيل"},{"Coming up","قريبًا"}};for(String[] p:words)Loc.AR.put(p[0],p[1]);}
 static final class Row {String id;boolean visible,pinned;Row(String key,boolean on,boolean pin){id=key;visible=on;pinned=pin;}}
 static List<Row> resolve(JSONArray saved,Collection<String> available){Set<String> known=new LinkedHashSet<>(DEFAULTS);known.addAll(available);List<Row> rows=new ArrayList<>();Set<String> seen=new HashSet<>();rows.add(new Row("continue",true,false));seen.add("continue");for(JSONObject value:DataStore.objects(saved)){String id=value.optString("id");if(known.contains(id)&&seen.add(id))rows.add(new Row(id,value.optBoolean("visible",true),value.optBoolean("pinned")));}for(String id:known)if(seen.add(id))rows.add(new Row(id,DEFAULTS.contains(id),false));return rows;}
 static JSONArray encode(List<Row> rows){JSONArray saved=new JSONArray();for(Row row:rows){JSONObject value=new JSONObject();DataStore.put(value,"id",row.id);DataStore.put(value,"visible",row.id.equals("continue")||row.visible);DataStore.put(value,"pinned",row.pinned);saved.put(value);}return saved;}
 final MainActivity a;final Map<String,Runnable> builders=new LinkedHashMap<>();final Map<String,String> names=new HashMap<>();String libraryType="All";boolean plannedOnly=false;
 HomeLayout(MainActivity activity){a=activity;}
 String name(String id){if(names.containsKey(id))return names.get(id);String value;switch(id){case "continue":value="Continue Watching";break;case "list":value="My List";break;case "top10":value="Top 10 this week";break;case "because":value="Because you watched…";break;case "genres":value="Genres";break;case "collections":value="Collections";break;case "recently-added":value="Recently added";break;case "services":value="Your services";break;case "recently-watched":value="Recently watched";break;case "shows":value="Your shows";break;case "movies":value="Your movies";break;case "queue":value="Your play queue";break;default:value="Coming up";}return Loc.t(value);}
 void render(List<List<JSONObject>> groups){builders.clear();names.clear();List<List<JSONObject>> recent=new ArrayList<>(groups);recent.sort((x,y)->Long.compare(MainActivity.recent(y),MainActivity.recent(x)));List<List<JSONObject>> watched=new ArrayList<>(),listed=new ArrayList<>(),shows=new ArrayList<>(),movies=new ArrayList<>();Set<String> genres=new TreeSet<>(),collections=new TreeSet<>();for(List<JSONObject> g:recent){JSONObject i=g.get(0);if(g.stream().anyMatch(DataStore::watched))watched.add(g);if(i.optBoolean("listed"))listed.add(g);if(a.inLibrary(g)){(i.optBoolean("movie")?movies:shows).add(g);genres.addAll(genre(i));}for(Object value:jsonValues(i.optJSONArray("collections")))collections.add(String.valueOf(value));}
  builders.put("list",()->rail("My List",listed));builders.put("top10",()->a.harbor.topTenRail(a.body));builders.put("services",()->a.harbor.servicesRow(a.body));builders.put("recently-watched",()->rail("Recently watched",watched));builders.put("shows",()->rail("Your shows",shows));builders.put("movies",()->rail("Your movies",movies));builders.put("upcoming",()->a.ui.comingUp(a.body));
  builders.put("recently-added",()->{List<List<JSONObject>> added=new ArrayList<>(groups);added.removeIf(g->g.stream().noneMatch(i->DataStore.date(i.optString("addedAt"))>0));added.sort((x,y)->Long.compare(added(y),added(x)));rail("Recently added",added);});
  builders.put("queue",()->{List<View> cards=new ArrayList<>();for(Object value:jsonValues(a.data.playQueue())){JSONObject i=a.data.item(String.valueOf(value));if(i==null)continue;List<JSONObject> g=a.group(i.optString("group"));if(g!=null)cards.add(a.ui.posterCard(g));}a.ui.rail(a.body,"Your play queue","",cards,null);});
  builders.put("because",()->{if(watched.isEmpty())return;JSONObject seed=watched.get(0).get(0);Set<String> tastes=genre(seed);List<List<JSONObject>> picks=new ArrayList<>();for(List<JSONObject> g:groups)if(!g.get(0).optString("group").equals(seed.optString("group"))&&g.stream().noneMatch(DataStore::watched)&&!Collections.disjoint(tastes,genre(g.get(0))))picks.add(g);rail(Loc.f("Because you watched %s",seed.optString("title")),picks);});
  builders.put("genres",()->{int n=0;for(String genre:genres){if(n++>=3)break;genreRow(genre,groups);}});for(String genre:genres){String id="genre:"+genre;names.put(id,Loc.t(genre));builders.put(id,()->genreRow(genre,groups));}
  builders.put("collections",()->{int n=0;for(String collection:collections){if(n++>=3)break;collectionRow(collection,groups);}});for(String collection:collections){String id="collection:"+collection;names.put(id,collection);builders.put(id,()->collectionRow(collection,groups));}
  for(Row row:resolve(a.data.prefs().optJSONArray("homeLayout"),builders.keySet()))if(row.visible&&builders.containsKey(row.id))builders.get(row.id).run();TextView edit=a.ui.chip("Edit Home",this::edit,false);LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(-2,-2);ep.setMargins(0,a.dp(30),0,a.dp(20));a.body.addView(edit,ep);
 }
 static List<Object> jsonValues(JSONArray a){List<Object> values=new ArrayList<>();if(a!=null)for(int i=0;i<a.length();i++)values.add(a.opt(i));return values;}
 static Set<String> genre(JSONObject i){Set<String> values=new LinkedHashSet<>();Object raw=i.opt("genres");if(raw instanceof JSONArray)for(Object value:jsonValues((JSONArray)raw))values.add(String.valueOf(value));else if(raw!=null)for(String value:String.valueOf(raw).split("[·,]"))if(!value.trim().isEmpty())values.add(value.trim());return values;}
 static long added(List<JSONObject> g){long at=0;for(JSONObject i:g)at=Math.max(at,DataStore.date(i.optString("addedAt")));return at;}
 void genreRow(String genre,List<List<JSONObject>> groups){List<List<JSONObject>> picks=new ArrayList<>();for(List<JSONObject> g:groups)if(genre(g.get(0)).contains(genre))picks.add(g);rail(genre,picks);}
 void collectionRow(String name,List<List<JSONObject>> groups){List<List<JSONObject>> picks=new ArrayList<>();for(List<JSONObject> g:groups)if(a.premium.member(g.get(0),name))picks.add(g);rail(name,picks);}
 void rail(String title,List<List<JSONObject>> groups){a.ui.rail(a.body,title,"",a.posters(groups,30),null);}
 void edit(){List<Row> rows=resolve(a.data.prefs().optJSONArray("homeLayout"),builders.keySet());LinearLayout content=a.column();content.setPadding(a.dp(16),a.dp(10),a.dp(16),a.dp(10));TextView note=a.text("Continue Watching stays first. Pin genres and collections below.",13,MainActivity.MUTED);content.addView(note);LinearLayout list=a.column();content.addView(list);Runnable[] draw=new Runnable[1];draw[0]=()->{list.removeAllViews();for(Row row:rows){boolean locked=row.id.equals("continue"),extra=row.id.contains(":");LinearLayout line=new LinearLayout(a);line.setGravity(Gravity.CENTER_VERTICAL);Switch eye=new Switch(a);eye.setText((locked?"🔒 ":extra?"☆ ":"")+name(row.id));eye.setTextColor(MainActivity.WHITE);eye.setTextSize(14);eye.setChecked(row.visible);eye.setEnabled(!locked);eye.setContentDescription(Loc.t(extra?"Pin row":"Show row")+" "+name(row.id));eye.setOnCheckedChangeListener((b,on)->{row.visible=on;row.pinned=extra&&on;});line.addView(eye,new LinearLayout.LayoutParams(0,a.dp(56),1));for(int delta:new int[]{-1,1}){int d=delta;TextView move=a.ui.small(d<0?"▲":"▼",()->{int at=rows.indexOf(row),target=at+d;if(target<1||target>=rows.size())return;rows.remove(at);rows.add(target,row);draw[0].run();},false);move.setContentDescription(Loc.t(d<0?"Move earlier":"Move later")+" "+name(row.id));boolean enabled=!locked&&(d<0?rows.indexOf(row)>1:rows.indexOf(row)<rows.size()-1);move.setEnabled(enabled);move.setAlpha(enabled?1:.25f);line.addView(move);}list.addView(line);}};draw[0].run();ScrollView scroll=new ScrollView(a);scroll.addView(content);AlertDialog dialog=new AlertDialog.Builder(a).setTitle(Loc.t("Make Home yours")).setView(scroll).setNegativeButton(Loc.t("Cancel"),null).setPositiveButton(Loc.t("Save Home"),(d,w)->{a.data.pref("homeLayout",encode(rows));a.render();}).create();dialog.show();}
 String viewKey(){return "libraryView:"+(a.premium.collection.equals("My List")?"My List":libraryType);}
 String mode(){String v=a.data.prefs().optString(viewKey(),"Poster");return Arrays.asList("Poster","Landscape","List").contains(v)?v:"Poster";}
 String size(){String v=a.data.prefs().optString(viewKey()+":size","Medium");return Arrays.asList("Small","Medium","Large").contains(v)?v:"Medium";}
 void libraryControls(){LinearLayout types=new LinearLayout(a);for(String type:new String[]{"All","Shows","Movies"})types.addView(a.ui.chip(type,()->{libraryType=type;a.render();},type.equals(libraryType)));a.body.addView(a.ui.row(types));LinearLayout options=new LinearLayout(a);options.addView(a.ui.chip(Loc.t("View")+" · "+Loc.t(mode()),()->choose("View",new String[]{"Poster","Landscape","List"},viewKey()),false));options.addView(a.ui.chip(Loc.t("Card size")+" · "+Loc.t(size()),()->choose("Card size",new String[]{"Small","Medium","Large"},viewKey()+":size"),false));a.body.addView(a.ui.row(options));if(a.premium.collection.equals("My List"))a.body.addView(a.ui.chip("Still planned",()->{plannedOnly=!plannedOnly;a.render();},plannedOnly));}
 void choose(String title,String[] values,String key){String[] labels=Arrays.stream(values).map(Loc::t).toArray(String[]::new);new AlertDialog.Builder(a).setTitle(Loc.t(title)).setItems(labels,(d,n)->{a.data.pref(key,values[n]);a.renderKeep();}).show();}
 static Rect bounds(View v){Rect b=new Rect();v.getGlobalVisibleRect(b);return b;}
 static void enter(View body,Rect source){if(source==null||source.isEmpty()||!Motion.enabled(body))return;body.post(()->{if(!body.isAttachedToWindow())return;int[] at=new int[2];body.getLocationOnScreen(at);body.setPivotX(Math.max(0,Math.min(body.getWidth(),source.exactCenterX()-at[0])));body.setPivotY(Math.max(0,source.exactCenterY()-at[1]));body.setAlpha(0);body.setScaleX(.88f);body.setScaleY(.88f);body.animate().scaleX(1).scaleY(1).alpha(1).setStartDelay(0).setDuration(240).start();});}
 static void tint(View image,String key){View v=image;while(v.getParent() instanceof View){v=(View)v.getParent();if("art-tint".equals(v.getTag())){int color=Motion.placeholder(key);GradientDrawable tint=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{color,MainActivity.BLACK});v.setBackground(tint);break;}}}
}
